import torch
import torch.nn as nn
from torch.nn.modules.utils import _triple
from torch.utils.cpp_extension import load_inline


_cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int ID, int IH, int IW,
    int OC, int OD, int OH, int OW,
    int KD, int KH, int KW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups,
    int IC_per_group,
    int OC_per_group)
{
    const int ox = static_cast<int>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int oy = static_cast<int>(blockIdx.y) * blockDim.y + threadIdx.y;

    if (ox >= OW || oy >= OH) {
        return;
    }

    const int z = static_cast<int>(blockIdx.z);
    const int oz = z % OD;
    const int oc_block = z / OD;
    const int ocl = oc_block % OC;
    const int n = oc_block / OC;

    if (n >= N) {
        return;
    }

    const int group = ocl / OC_per_group;
    const int oc_local = ocl - group * OC_per_group;

    float acc = bias != nullptr ? bias[ocl] : 0.0f;

    for (int kz = 0; kz < KD; ++kz) {
        const int tz = oz + pad_d - kz * dil_d;
        if (tz < 0 || (tz % stride_d) != 0) {
            continue;
        }

        const int iz = tz / stride_d;
        if (iz < 0 || iz >= ID) {
            continue;
        }

        for (int ky = 0; ky < KH; ++ky) {
            const int ty = oy + pad_h - ky * dil_h;
            if (ty < 0 || (ty % stride_h) != 0) {
                continue;
            }

            const int iy = ty / stride_h;
            if (iy < 0 || iy >= IH) {
                continue;
            }

            for (int kx = 0; kx < KW; ++kx) {
                const int tx = ox + pad_w - kx * dil_w;
                if (tx < 0 || (tx % stride_w) != 0) {
                    continue;
                }

                const int ix = tx / stride_w;
                if (ix < 0 || ix >= IW) {
                    continue;
                }

                for (int ic_local = 0; ic_local < IC_per_group; ++ic_local) {
                    const int ic = group * IC_per_group + ic_local;

                    const int64_t x_idx =
                        (((static_cast<int64_t>(n) * IC + ic) * ID + iz) * IH + iy) * IW + ix;

                    const int64_t w_idx =
                        ((((static_cast<int64_t>(ic) * OC_per_group + oc_local) * KD + kz)
                           * KH + ky) * KW + kx);

                    acc += x[x_idx] * weight[w_idx];
                }
            }
        }
    }

    const int64_t out_idx =
        (((static_cast<int64_t>(n) * OC + ocl) * OD + oz) * OH + oy) * OW + ox;

    out[out_idx] = acc;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t output_pad_d, int64_t output_pad_h, int64_t output_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(!bias.defined() || bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 tensors are supported");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "only float32 tensors are supported");
    TORCH_CHECK(!bias.defined() || bias.scalar_type() == at::kFloat,
                "only float32 tensors are supported");
    TORCH_CHECK(x.dim() == 5, "x must have shape (N, C, D, H, W)");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape (IC, OC/groups, KD, KH, KW)");

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();
    torch::Tensor bias_contig;
    if (bias.defined()) {
        bias_contig = bias.contiguous();
    }

    const int N = static_cast<int>(x_contig.size(0));
    const int IC = static_cast<int>(x_contig.size(1));
    const int ID = static_cast<int>(x_contig.size(2));
    const int IH = static_cast<int>(x_contig.size(3));
    const int IW = static_cast<int>(x_contig.size(4));

    const int OC = static_cast<int>(weight_contig.size(1) * groups);
    const int KD = static_cast<int>(weight_contig.size(2));
    const int KH = static_cast<int>(weight_contig.size(3));
    const int KW = static_cast<int>(weight_contig.size(4));

    const int OD = static_cast<int>(
        (ID - 1) * stride_d - 2 * pad_d + dil_d * (KD - 1) + output_pad_d + 1);
    const int OH = static_cast<int>(
        (IH - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + output_pad_h + 1);
    const int OW = static_cast<int>(
        (IW - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + output_pad_w + 1);

    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(OC % groups == 0, "output channels must be divisible by groups");

    const int IC_per_group = IC / static_cast<int>(groups);
    const int OC_per_group = OC / static_cast<int>(groups);

    auto out = torch::empty({N, OC, OD, OH, OW}, x_contig.options());

    const dim3 block(8, 8, 1);
    const dim3 grid(
        (OW + block.x - 1) / block.x,
        (OH + block.y - 1) / block.y,
        N * OC * OD);

    at::cuda::CUDAGuard device_guard(x_contig.device());
    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    conv_transpose3d_kernel<<<grid, block, 0, stream>>>(
        x_contig.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias.defined() ? bias_contig.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N, IC, ID, IH, IW,
        OC, OD, OH, OW,
        KD, KH, KW,
        static_cast<int>(stride_d),
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_d),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_d),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        static_cast<int>(groups),
        IC_per_group,
        OC_per_group);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
'''

_cpp_src = r'''
#include <torch/extension.h>

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t output_pad_d, int64_t output_pad_h, int64_t output_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose3d", &conv_transpose3d_cuda,
          "Custom CUDA ConvTranspose3d");
}
'''

_conv_transpose3d_ext = load_inline(
    name="custom_conv_transpose3d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=None,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            _triple(kernel_size),
            stride=_triple(stride),
            padding=_triple(padding),
            output_padding=_triple(output_padding),
            dilation=_triple(dilation),
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d

        stride_d, stride_h, stride_w = _triple(conv.stride)
        pad_d, pad_h, pad_w = _triple(conv.padding)
        out_pad_d, out_pad_h, out_pad_w = _triple(conv.output_padding)
        dil_d, dil_h, dil_w = _triple(conv.dilation)

        if conv.bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        else:
            bias = conv.bias

        return _conv_transpose3d_ext.conv_transpose3d(
            x,
            conv.weight,
            bias,
            stride_d,
            stride_h,
            stride_w,
            pad_d,
            pad_h,
            pad_w,
            out_pad_d,
            out_pad_h,
            out_pad_w,
            dil_d,
            dil_h,
            dil_w,
            conv.groups,
        )

